(7051093, 1071794, 11769, '<td valign="top">colorful abstract</td>', 'colorful abstract', '2013-06-11 15:45:05.000000', NULL, 1),
(7051116, 1071830, 94815, '<td valign="top">You must have been thinking of the Bernini sculpture of Daphne pursued by Apollo. The missed focus works to blend her into the leaves as we witness her metamorphoses.</td>', 'You must have been thinking of the Bernini sculpture of Daphne pursued by Apollo. The missed focus works to blend her into the leaves as we witness her metamorphoses.', '2013-06-11 17:38:05.000000', NULL, 1),
(7051117, 1071062, 94815, '<td valign="top">Lucky bird.</td>', 'Lucky bird.', '2013-06-11 17:38:51.000000', NULL, 1),
(7051118, 1071874, 94815, '<td valign="top">Effective even without the title.</td>', 'Effective even without the title.', '2013-06-11 17:39:28.000000', NULL, 1),
(7051119, 1071777, 94815, '<td valign="top">I like the way the focused lower left draws my attention and leaves the rest as peripherally seen.</td>', 'I like the way the focused lower left draws my attention and leaves the rest as peripherally seen.', '2013-06-11 17:41:51.000000', NULL, 1),
(7051120, 1071719, 94815, '<td valign="top">The intensely delineated bokeh distracts on first glance and the flower follows on the double take. Nice color.</td>', 'The intensely delineated bokeh distracts on first glance and the flower follows on the double take. Nice color.', '2013-06-11 17:44:14.000000', NULL, 1),
(7051121, 1071740, 94815, '<td valign="top">The edgey thorns make an unfriendly statement. The peripheral blur offers something nicer. Good conflict.</td>', 'The edgey thorns make an unfriendly statement. The peripheral blur offers something nicer. Good conflict.', '2013-06-11 17:46:55.000000', NULL, 1),
(7051123, 1071757, 94815, '<td valign="top">Difficult to feel that this is "missed" - more like something we most likely would have "missed" if you had not shown it. Good demo of how the focus can dramatically change the subject. I''m enjoying the casual everydayness of this with a specifically highlighted bite, so to speak.</td>', 'Difficult to feel that this is "missed" - more like something we most likely would have "missed" if you had not shown it. Good demo of how the focus can dramatically change the subject. I''m enjoying the casual everydayness of this with a specifically highlighted bite, so to speak.', '2013-06-11 17:51:22.000000', NULL, 1),
(7051125, 1071889, 94815, '<td valign="top">I feel there is something philosophical that should be said as an illustration of reality and perception. But I''m lost for words. All I know is that I''m enjoying it in the way is tugs at my neurons. Visually its a tug of war between the sharply detailed background and the oof bottles - as if their contents have escaped only to be captured on the glass panes. Oh well enough of that.</td>', 'I feel there is something philosophical that should be said as an illustration of reality and perception. But I''m lost for words. All I know is that I''m enjoying it in the way is tugs at my neurons. Visually its a tug of war between the sharply detailed background and the oof bottles - as if their contents have escaped only to be captured on the glass panes. Oh well enough of that.', '2013-06-11 17:59:38.000000', NULL, 1),
(7051126, 1071885, 94815, '<td valign="top">Flighty pop-arty stuff. I like the mood.</td>', 'Flighty pop-arty stuff. I like the mood.', '2013-06-11 18:00:23.000000', NULL, 1),
(7051148, 1071139, 18367, '<td valign="top">I absolutely love this and hope that I see it on the front page at the end of the challenge.  Very well done indeed.</td>', 'I absolutely love this and hope that I see it on the front page at the end of the challenge.  Very well done indeed.', '2013-06-11 19:14:14.000000', NULL, 1),
(7051154, 1071942, 114225, '<td valign="top">Oh, this has power. The stalking animal with the red eyes locked on the unsuspecting target.</td>', 'Oh, this has power. The stalking animal with the red eyes locked on the unsuspecting target.', '2013-06-11 20:08:11.000000', NULL, 1),
(7051155, 1071508, 114225, '<td valign="top">Funny, my subject would be the snake. Which you hit focus well.</td>', 'Funny, my subject would be the snake. Which you hit focus well.', '2013-06-11 20:08:37.000000', NULL, 1),
(7051156, 1071825, 114225, '<td valign="top">Heh, that is a nice example of what this challenge is about.</td>', 'Heh, that is a nice example of what this challenge is about.', '2013-06-11 20:09:17.000000', NULL, 1),
(7051157, 1071898, 114225, '<td valign="top">The missed focus gives this a nice dream feeling.</td>', 'The missed focus gives this a nice dream feeling.', '2013-06-11 20:09:32.000000', NULL, 1),
(7051158, 1071950, 114225, '<td valign="top">Just a distant memory now.</td>', 'Just a distant memory now.', '2013-06-11 20:11:41.000000', NULL, 1),
